def port_bounds(value):
    if not isinstance(value, str):
        raise Unavailable("malformed allowed port")
    parts = value.split("-")
    if len(parts) not in (1, 2) or any(not part.isdigit() for part in parts):
        raise Unavailable("malformed allowed port range")
